SELECT DISTINCTROW RECLAMI2.[Record numero], RECLAMI2.[Reclamo numero], RECLAMI2.[Numero risposta], RECLAMI2.Data, RECLAMI2.Commessa, RECLAMI2.[Famiglia dei prodotti], RECLAMI2.[Kg reclamati], RECLAMI2.Motivazioni, RECLAMI2.Difetto, RECLAMI2.[Data risposta], RECLAMI2.Soluzione, RECLAMI2.Contabilità, RECLAMI2.Risposta, RECLAMI2.Commento, RECLAMI2.[Kg resi], RECLAMI2.Esterno, RECLAMI2.[Nota di credito], RECLAMI2.Accredito, RECLAMI2.Note, RECLAMI2.[Ufficio 1], RECLAMI2.[Ufficio 2], RECLAMI2.[Ufficio 3], RECLAMI2.[Ufficio 4], RECLAMI2.[Ufficio 5], RECLAMI2.[Ufficio 6], RECLAMI2.[Invia a]
FROM RECLAMI2 INNER JOIN DATI ON RECLAMI2.Commessa = DATI.NUMCOMM
WHERE ((RECLAMI2.[Numero risposta] Like [inserire il numero di risposta]));
